import 'package:flutter/material.dart'; import 'package:flutter_test/flutter_test.dart'; import 'package:eye_control/presentation/widgets/status_card.dart'; import 'package:eye_control/presentation/widgets/permission_tile.dart'; import 'package:eye_control/presentation/widgets/empty_state.dart'; void main(){testWidgets('shared widgets render semantic content',(tester)async{await tester.pumpWidget(const MaterialApp(home:Column(children:[StatusCard(ready:true,title:'Ready',subtitle:'OK'),PermissionTile(icon:Icons.camera,title:'Camera',subtitle:'Local',granted:false,onPressed:null),EmptyState(icon:Icons.info,title:'Empty',subtitle:'None')])));expect(find.text('Ready'),findsOneWidget);expect(find.text('Camera'),findsOneWidget);expect(find.text('Empty'),findsOneWidget);});}